2130:+		4 => array('n'),
2131:+		5 => array('span'),
2132:+		8 => array('flex'),
2133:+		9 => array('weights'),
2134:+		10 => array('alpha'),
2135:+		11 => array('alpha', 'beta'),
2136:+		12 => array('alpha', 'beta', 'gamma', 'season')
2137:+	);
2138:+	return isset($Keys[$Method]) ? $Keys[$Method] : array();
2139:+}
2140:+
