2143:+		'p' => __('Percent over last year'),
2144:+		'n' => __('Moving average periods'),
2145:+		'span' => __('Months between the two points'),
2146:+		'flex' => __('Weights of the prior 12 months'),
2147:+		'weights' => __('Weights, most recent period first'),
2148:+		'alpha' => __('Alpha'),
