2290:+/* ------------------------------------------------------------------- methods */
2291:+
2292:+/* Forecasts $Horizon months after the end of $Series with $Method.
2293:+Returns array('values' => list of quantities, never negative) or array('error' => reason) */
2294:+function ForecastCompute($Method, $Series, $Horizon, $Params) {
2295:+	$Series = array_values($Series);
2296:+	$n = count($Series);
2297:+	$Min = ForecastMethodMinHistory($Method);
2298:+	if ($Min === null) {
2299:+		return array('error' => __('Unknown forecasting method'));
2300:+	}
2301:+	if ($n < $Min) {
2302:+		return array('error' => sprintf(__('Only %d months of history, the method needs at least %d'), $n, $Min));
2303:+	}
2304:+	$Horizon = (int) $Horizon;
2305:+	$F = array();
2306:+
2307:+	switch ($Method) {
2308:+		case 1: // percent over last year
2309:+		case 2: // calculated percent over last year
2310:+		case 3: // last year to this year
2311:+			if ($Method == 1) {
2312:+				$Factor = 1 + $Params['p'] / 100;
2313:+			} elseif ($Method == 3) {
2314:+				$Factor = 1;
2315:+			} else {
2316:+				$LastYear = array_sum(array_slice($Series, $n - 12, 12));
2317:+				$YearBefore = array_sum(array_slice($Series, $n - 24, 12));
2318:+				if ($YearBefore <= 0) {
2319:+					return array('error' => __('There were no sales in the year before last year, so the growth cannot be calculated'));
2320:+				}
2321:+				$Factor = $LastYear / $YearBefore;
2322:+			}
2323:+			// beyond 12 months the "same month last year" is itself a forecast
2324:+			$Extended = $Series;
2325:+			for ($k = 1; $k <= $Horizon; $k++) {
2326:+				$Value = max(0, $Extended[$n + $k - 1 - 12] * $Factor);
2327:+				$Extended[] = $Value;
2328:+				$F[] = $Value;
2329:+			}
2330:+			break;
2331:+
2332:+		case 4: // moving average of the last N periods
2333:+			$N = (int) $Params['n'];
2334:+			if ($N < 2 or $N > $n) {
2335:+				return array('error' => sprintf(__('The moving average of %d periods needs at least that many months of history'), $N));
2336:+			}
2337:+			$Average = array_sum(array_slice($Series, $n - $N, $N)) / $N;
2338:+			$F = array_fill(0, $Horizon, max(0, $Average));
2339:+			break;
2340:+
2341:+		case 5: // line through two historical points
2342:+			$Span = (int) $Params['span'];
2343:+			if ($Span < 2 or $Span > $n) {
2344:+				return array('error' => sprintf(__('The two points are %d months apart but there are only %d months of history'), $Span, $n));
2345:+			}
2346:+			$Last = $Series[$n - 1];
2347:+			$Slope = ($Last - $Series[$n - $Span]) / ($Span - 1);
2348:+			for ($k = 1; $k <= $Horizon; $k++) {
2349:+				$F[] = max(0, $Last + $Slope * $k);
2350:+			}
2351:+			break;
2352:+
2353:+		case 6: // least squares line over all history
2354:+			$SumT = 0;
2355:+			$SumT2 = 0;
2356:+			$SumY = 0;
2357:+			$SumTY = 0;
2358:+			for ($i = 0; $i < $n; $i++) {
2359:+				$t = $i + 1;
2360:+				$SumT += $t;
2361:+				$SumT2 += $t * $t;
2362:+				$SumY += $Series[$i];
2363:+				$SumTY += $t * $Series[$i];
2364:+			}
2365:+			$Denominator = $n * $SumT2 - $SumT * $SumT;
2366:+			$B = ($n * $SumTY - $SumT * $SumY) / $Denominator;
2367:+			$A = ($SumY - $B * $SumT) / $n;
2368:+			for ($k = 1; $k <= $Horizon; $k++) {
2369:+				$F[] = max(0, $A + $B * ($n + $k));
2370:+			}
2371:+			break;
2372:+
2373:+		case 7: // least squares parabola over all history, on centred time to keep the equations well conditioned
2374:+			$Mean = ($n + 1) / 2;
2375:+			$S2 = 0;
2376:+			$S4 = 0;
2377:+			$SumY = 0;
2378:+			$SumXY = 0;
2379:+			$SumX2Y = 0;
2380:+			for ($i = 0; $i < $n; $i++) {
2381:+				$x = ($i + 1) - $Mean;
2382:+				$S2 += $x * $x;
2383:+				$S4 += $x * $x * $x * $x;
2384:+				$SumY += $Series[$i];
2385:+				$SumXY += $x * $Series[$i];
2386:+				$SumX2Y += $x * $x * $Series[$i];
2387:+			}
2388:+			$Determinant = $n * $S4 - $S2 * $S2;
2389:+			if ($Determinant <= 0 or $S2 <= 0) {
2390:+				return array('error' => __('The second degree approximation cannot be solved for this history'));
2391:+			}
2392:+			$A = ($SumY * $S4 - $S2 * $SumX2Y) / $Determinant;
2393:+			$B = $SumXY / $S2;
2394:+			$C = ($n * $SumX2Y - $S2 * $SumY) / $Determinant;
2395:+			for ($k = 1; $k <= $Horizon; $k++) {
2396:+				$x = ($n + $k) - $Mean;
2397:+				$F[] = max(0, $A + $B * $x + $C * $x * $x);
2398:+			}
2399:+			break;
2400:+
2401:+		case 8: // flexible: the user's weights on each of the prior 12 months, not normalised
2402:+			$Weights = array_values($Params['flex']);
2403:+			if (count($Weights) != 12 or array_sum($Weights) <= 0) {
2404:+				return array('error' => __('Enter exactly 12 flexible weights, one for each of the prior 12 months, that add up to more than zero'));
2405:+			}
2406:+			$Extended = $Series;
2407:+			for ($k = 1; $k <= $Horizon; $k++) {
2408:+				$Index = $n + $k - 1;
2409:+				$Value = 0;
2410:+				for ($Lag = 1; $Lag <= 12; $Lag++) {
2411:+					$Value += $Weights[$Lag - 1] * $Extended[$Index - $Lag];
2412:+				}
2413:+				$Value = max(0, $Value);
2414:+				$Extended[] = $Value;
2415:+				$F[] = $Value;
2416:+			}
2417:+			break;
2418:+
2419:+		case 9: // weighted moving average, weights listed most recent period first
2420:+			$Weights = array_values($Params['weights']);
2421:+			$N = count($Weights);
2422:+			if ($N < 2 or $N > $n or array_sum($Weights) <= 0) {
2423:+				return array('error' => sprintf(__('The %d weights need at least that many months of history and must add up to more than zero'), $N));
2424:+			}
2425:+			$Value = 0;
2426:+			for ($i = 0; $i < $N; $i++) {
2427:+				$Value += $Weights[$i] * $Series[$n - 1 - $i];
2428:+			}
2429:+			$F = array_fill(0, $Horizon, max(0, $Value / array_sum($Weights)));
2430:+			break;
2431:+
2432:+		case 10: // simple exponential smoothing
2433:+			$Alpha = $Params['alpha'];
2434:+			$Level = $Series[0];
2435:+			for ($i = 1; $i < $n; $i++) {
2436:+				$Level = $Alpha * $Series[$i] + (1 - $Alpha) * $Level;
2437:+			}
2438:+			$F = array_fill(0, $Horizon, max(0, $Level));
2439:+			break;
2440:+
2441:+		case 11: // Holt double exponential smoothing
2442:+			$Alpha = $Params['alpha'];
2443:+			$Beta = $Params['beta'];
2444:+			$Level = $Series[0];
2445:+			$Reach = min(3, $n - 1);
2446:+			$Trend = ($Series[$Reach] - $Series[0]) / $Reach;
2447:+			for ($i = 1; $i < $n; $i++) {
2448:+				$Previous = $Level;
2449:+				$Level = $Alpha * $Series[$i] + (1 - $Alpha) * ($Previous + $Trend);
2450:+				$Trend = $Beta * ($Level - $Previous) + (1 - $Beta) * $Trend;
2451:+			}
2452:+			for ($k = 1; $k <= $Horizon; $k++) {
2453:+				$F[] = max(0, $Level + $k * $Trend);
2454:+			}
2455:+			break;
2456:+
2457:+		case 12: // Holt-Winters, additive seasonality
2458:+			$Alpha = $Params['alpha'];
2459:+			$Beta = $Params['beta'];
2460:+			$Gamma = $Params['gamma'];
2461:+			$L = (int) $Params['season'];
2462:+			if ($L < 2 or $n < 2 * $L) {
2463:+				return array('error' => sprintf(__('A season of %d months needs at least %d months of history'), $L, 2 * $L));
2464:+			}
2465:+			$Mean1 = array_sum(array_slice($Series, 0, $L)) / $L;
2466:+			$Mean2 = array_sum(array_slice($Series, $L, $L)) / $L;
2467:+			$Trend = ($Mean2 - $Mean1) / $L;
2468:+			$Level = $Mean1 + $Trend * ($L - 1) / 2;
2469:+			$Seasonal = array();
2470:+			for ($i = 0; $i < $L; $i++) {
2471:+				$Seasonal[$i] = (($Series[$i] - $Mean1) + ($Series[$L + $i] - $Mean2)) / 2;
2472:+			}
2473:+			for ($t = $L; $t < $n; $t++) {
2474:+				$Previous = $Level;
2475:+				$Level = $Alpha * ($Series[$t] - $Seasonal[$t % $L]) + (1 - $Alpha) * ($Previous + $Trend);
2476:+				$Trend = $Beta * ($Level - $Previous) + (1 - $Beta) * $Trend;
2477:+				$Seasonal[$t % $L] = $Gamma * ($Series[$t] - $Level) + (1 - $Gamma) * $Seasonal[$t % $L];
2478:+			}
2479:+			for ($k = 1; $k <= $Horizon; $k++) {
2480:+				$F[] = max(0, $Level + $k * $Trend + $Seasonal[($n + $k - 1) % $L]);
2481:+			}
2482:+			break;
2483:+	}
2484:+
2485:+	foreach ($F as $Index => $Value) {
2486:+		$F[$Index] = round($Value, 2);
2487:+	}
2488:+	return array('values' => $F);
2489:+}
2490:+
2491:+/* ------------------------------------------------------------ accuracy measures */
2492:+
2493:+/* Sums that can be added up across items, categories or methods before the measures are derived */
2494:+function ForecastErrorSums($Actual, $Forecast) {
2495:+	$Sums = array('n' => 0, 'abs' => 0, 'sq' => 0, 'actual' => 0, 'forecast' => 0);
2496:+	$Count = min(count($Actual), count($Forecast));
2497:+	$Actual = array_values($Actual);
2498:+	$Forecast = array_values($Forecast);
2499:+	for ($i = 0; $i < $Count; $i++) {
2500:+		$Error = $Forecast[$i] - $Actual[$i];
2501:+		$Sums['n']++;
2502:+		$Sums['abs'] += abs($Error);
2503:+		$Sums['sq'] += $Error * $Error;
2504:+		$Sums['actual'] += $Actual[$i];
2505:+		$Sums['forecast'] += $Forecast[$i];
2506:+	}
2507:+	return $Sums;
2508:+}
2509:+
2510:+function ForecastAddSums($Total, $Sums) {
2511:+	foreach ($Sums as $Key => $Value) {
2512:+		$Total[$Key] = (isset($Total[$Key]) ? $Total[$Key] : 0) + $Value;
2513:+	}
2514:+	return $Total;
2515:+}
2516:+
2517:+/* MAD mean absolute deviation, MSE mean squared error, RMSE its root, POA percent of accuracy and the bias.
2518:+POA = 100 x (1 - total absolute error / total actual), never below 0: 100 is a perfect forecast, so
2519:+under- and over-forecasts that cancel out do not hide poor accuracy. */
2520:+function ForecastMeasures($Sums) {
2521:+	if (empty($Sums['n'])) {
2522:+		return array('mad' => null, 'mse' => null, 'rmse' => null, 'poa' => null, 'bias' => null, 'n' => 0);
2523:+	}
2524:+	$MSE = $Sums['sq'] / $Sums['n'];
2525:+	if ($Sums['actual'] > 0) {
2526:+		$POA = max(0, 100 * (1 - $Sums['abs'] / $Sums['actual']));
2527:+		$Bias = 100 * ($Sums['forecast'] - $Sums['actual']) / $Sums['actual'];
2528:+	} else {
2529:+		$POA = ($Sums['abs'] == 0) ? 100 : 0;
2530:+		$Bias = null;
2531:+	}
2532:+	return array('mad' => $Sums['abs'] / $Sums['n'], 'mse' => $MSE, 'rmse' => sqrt($MSE), 'poa' => $POA, 'bias' => $Bias, 'n' => $Sums['n']);
2533:+}
2534:+
2535:+function ForecastFormatMeasure($Value, $Decimals = 2) {
2536:+	return ($Value === null) ? '-' : locale_number_format($Value, $Decimals);
2537:+}
2538:+
2539:+/* Holds out the most recent $Holdout months, forecasts them from the rest and measures the error.
2540:+Returns array('error' => reason) or array('sums' =>, 'forecast' =>, 'actual' =>) */
2541:+function ForecastEvaluate($Method, $Series, $Holdout, $Params) {
2542:+	$Series = array_values($Series);
2543:+	$n = count($Series);
2544:+	$Holdout = max(1, (int) $Holdout);
2545:+	if ($n - $Holdout < 1) {
2546:+		return array('error' => __('Not enough history to hold out months for the accuracy test'));
2547:+	}
2548:+	$Training = array_slice($Series, 0, $n - $Holdout);
2549:+	$Actual = array_slice($Series, $n - $Holdout);
2550:+	$Result = ForecastCompute($Method, $Training, $Holdout, $Params);
2551:+	if (isset($Result['error'])) {
2552:+		return $Result;
2553:+	}
2554:+	return array('sums' => ForecastErrorSums($Actual, $Result['values']), 'forecast' => $Result['values'], 'actual' => $Actual);
2555:+}
2556:+
2557:+/* Evaluates every method that has enough history and returns the one with the lowest total absolute error
2558:+(ties go to the lower method number).
2559:+array('best' => method or 0, 'results' => method => evaluation, 'errors' => method => reason) */
2560:+function ForecastBestFit($Series, $Holdout, $Params) {
2561:+	$Results = array();
2562:+	$Errors = array();
2563:+	$Best = 0;
2564:+	foreach (array_keys(ForecastMethodNames()) as $Method) {
2565:+		$Evaluation = ForecastEvaluate($Method, $Series, $Holdout, $Params);
2566:+		if (isset($Evaluation['error'])) {
2567:+			$Errors[$Method] = $Evaluation['error'];
2568:+			continue;
2569:+		}
2570:+		$Results[$Method] = $Evaluation;
2571:+		if ($Best == 0 or $Evaluation['sums']['abs'] < $Results[$Best]['sums']['abs'] - 0.0000001) {
2572:+			$Best = $Method;
2573:+		}
2574:+	}
2575:+	return array('best' => $Best, 'results' => $Results, 'errors' => $Errors);
2576:+}
