2580:+function ForecastAddMonths($MonthStart, $Months) {
2581:+	$Date = new DateTime($MonthStart);
2582:+	$Date->modify('first day of this month');
2583:+	if ($Months != 0) {
2584:+		$Date->modify(($Months > 0 ? '+' : '') . (int) $Months . ' month');
2585:+	}
2586:+	return $Date->format('Y-m-d');
2587:+}
