2589:+/* 'YYYY-MM' (month input) or any date to the first day of its month, or null when invalid */
2590:+function ForecastMonthStart($Text) {
2591:+	if (preg_match('/^(\d{4})-(\d{2})(-\d{2})?$/', trim($Text), $Matches) and $Matches[2] >= 1 and $Matches[2] <= 12) {
2592:+		return $Matches[1] . '-' . $Matches[2] . '-01';
2593:+	}
2594:+	return null;
2595:+}
