2605:+/* ---------------------------------------------------------- sales history */
2606:+
2607:+/* array('from' => first month, 'to' => last month, 'items' => count, 'months' => count, 'rows' => count),
2608:+'from' is null when no history is held */
2609:+function ForecastHistoryRange() {
2610:+	$Result = DB_query("SELECT MIN(monthstart) AS firstmonth,
2611:+							MAX(monthstart) AS lastmonth,
2612:+							COUNT(DISTINCT stockid) AS items,
2613:+							COUNT(DISTINCT monthstart) AS months,
2614:+							COUNT(*) AS historyrows
2615:+						FROM forecasthistory");
2616:+	$MyRow = DB_fetch_array($Result);
2617:+	return array('from' => $MyRow['firstmonth'], 'to' => $MyRow['lastmonth'], 'items' => (int) $MyRow['items'], 'months' => (int) $MyRow['months'], 'rows' => (int) $MyRow['historyrows']);
2618:+}
2619:+
2620:+/* Replaces the history of the months $From to $To (first days of months) with net invoiced sales: invoices (type 10)
2621:+less credit notes (type 11) from the stock movements, the same source as the inventory planning and sales reports.
2622:+Returns the number of history rows written. */
2623:+function ForecastExtractHistory($From, $To) {
2624:+	$LastDay = date('Y-m-t', strtotime($To));
2625:+	DB_Txn_Begin();
2626:+	DB_query("DELETE FROM forecasthistory WHERE monthstart >= '" . $From . "' AND monthstart <= '" . $To . "'", '', '', true);
2627:+	$Result = DB_query("INSERT INTO forecasthistory (stockid, loccode, monthstart, debtortype, area, salesman, qty)
2628:+						SELECT stockmoves.stockid,
2629:+							stockmoves.loccode,
2630:+							DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
2631:+							COALESCE(debtorsmaster.typeid, 0),
2632:+							COALESCE(custbranch.area, ''),
2633:+							COALESCE(custbranch.salesman, ''),
2634:+							-SUM(stockmoves.qty)
2635:+						FROM stockmoves
2636:+						LEFT JOIN debtorsmaster ON debtorsmaster.debtorno = stockmoves.debtorno
2637:+						LEFT JOIN custbranch ON custbranch.debtorno = stockmoves.debtorno
2638:+							AND custbranch.branchcode = stockmoves.branchcode
2639:+						WHERE stockmoves.type IN (10, 11)
2640:+							AND stockmoves.hidemovt = 0
2641:+							AND stockmoves.trandate >= '" . $From . "'
2642:+							AND stockmoves.trandate <= '" . $LastDay . "'
2643:+						GROUP BY stockmoves.stockid,
2644:+							stockmoves.loccode,
2645:+							DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
2646:+							COALESCE(debtorsmaster.typeid, 0),
2647:+							COALESCE(custbranch.area, ''),
2648:+							COALESCE(custbranch.salesman, '')", '', '', true);
2649:+	$Rows = DB_affected_rows($Result);
2650:+	DB_Txn_Commit();
2651:+	return $Rows;
2652:+}
2653:+
2654:+/* Turns month => quantity into a gap free series ending at $EndMonth. The series starts at the first month with
2655:+history: the months before an item's first sale are not history. Returns array('start' =>, 'end' =>, 'values' =>) */
2656:+function ForecastBuildSeries($MonthMap, $EndMonth) {
2657:+	if (count($MonthMap) == 0) {
2658:+		return array('start' => null, 'end' => $EndMonth, 'values' => array());
2659:+	}
2660:+	ksort($MonthMap);
2661:+	$Months = array_keys($MonthMap);
2662:+	$Start = $Months[0];
2663:+	$Values = array();
2664:+	$Month = $Start;
2665:+	while ($Month <= $EndMonth) {
2666:+		$Values[] = isset($MonthMap[$Month]) ? (float) $MonthMap[$Month] : 0.0;
2667:+		$Month = ForecastAddMonths($Month, 1);
2668:+	}
2669:+	return array('start' => $Start, 'end' => $EndMonth, 'values' => $Values);
2670:+}
2671:+
2672:+function ForecastLocationWhere($LocCode, $Table = 'forecasthistory') {
2673:+	if ($LocCode == FORECAST_ALL_LOCATIONS) {
2674:+		return '';
2675:+	}
2676:+	return " AND " . $Table . ".loccode = '" . $LocCode . "'";
2677:+}
2678:+
2679:+/* month => net quantity sold of one item at one location (or all locations) */
2680:+function ForecastItemMonths($StockID, $LocCode) {
2681:+	$Result = DB_query("SELECT monthstart, SUM(qty) AS qty
2682:+						FROM forecasthistory
2683:+						WHERE stockid = '" . $StockID . "'" . ForecastLocationWhere($LocCode) . "
2684:+						GROUP BY monthstart");
2685:+	$Map = array();
2686:+	while ($MyRow = DB_fetch_array($Result)) {
2687:+		$Map[$MyRow['monthstart']] = (float) $MyRow['qty'];
2688:+	}
2689:+	return $Map;
2690:+}
2691:+
2692:+function ForecastItemSeries($StockID, $LocCode, $HistoryEnd) {
2693:+	return ForecastBuildSeries(ForecastItemMonths($StockID, $LocCode), $HistoryEnd);
2694:+}
