2698:+/* Stores a forecast as the active one for the item and location; the previous active one is kept as superseded.
2699:+$Values is a list of quantities for the months following $HistoryTo. Returns the new forecast id. */
2700:+function ForecastSave($StockID, $LocCode, $Method, $Params, $HistoryFrom, $HistoryTo, $BestFit, $Values) {
2701:+	DB_Txn_Begin();
2702:+	DB_query("UPDATE forecasts SET activekey = NULL
2703:+				WHERE stockid = '" . $StockID . "'
2704:+				AND loccode = '" . $LocCode . "'
2705:+				AND activekey = 1", '', '', true);
2706:+	DB_query("INSERT INTO forecasts (stockid, loccode, method, methodparams, horizon, historyfrom, historyto, bestfit, activekey, createdby, createddate)
2707:+				VALUES ('" . $StockID . "',
2708:+					'" . $LocCode . "',
2709:+					'" . (int) $Method . "',
2710:+					'" . DB_escape_string(ForecastParamsEncode($Method, $Params)) . "',
2711:+					'" . count($Values) . "',
2712:+					'" . $HistoryFrom . "',
2713:+					'" . $HistoryTo . "',
2714:+					'" . ($BestFit ? 1 : 0) . "',
2715:+					1,
2716:+					'" . $_SESSION['UserID'] . "',
2717:+					NOW())", '', '', true);
2718:+	$ForecastID = DB_Last_Insert_ID('forecasts', 'forecastid');
2719:+	$Lines = array();
2720:+	$Month = ForecastAddMonths($HistoryTo, 1);
2721:+	foreach ($Values as $Value) {
2722:+		$Lines[] = "(" . $ForecastID . ", '" . $Month . "', " . (float) $Value . ")";
2723:+		$Month = ForecastAddMonths($Month, 1);
2724:+	}
2725:+	DB_query("INSERT INTO forecastlines (forecastid, periodstart, calcqty) VALUES " . implode(',', $Lines), '', '', true);
2726:+	DB_Txn_Commit();
2727:+	return $ForecastID;
2728:+}
