2759:+
2760:+/* Generates and stores the forecast of one item. $Method 0 asks for the best fit.
2761:+Returns array('error' => reason) or array('forecastid' =>, 'method' =>, 'values' =>, 'bestfit' => ForecastBestFit result or null) */
2762:+function ForecastGenerateItem($StockID, $LocCode, $Method, $Params, $Horizon, $Holdout, $HistoryEnd, $ChosenByBestFit = false) {
2763:+	$Series = ForecastItemSeries($StockID, $LocCode, $HistoryEnd);
2764:+	if (count($Series['values']) == 0) {
2765:+		return array('error' => __('There is no sales history for this item'));
2766:+	}
2767:+	$BestFit = null;
2768:+	if ($Method == 0) {
2769:+		$BestFit = ForecastBestFit($Series['values'], $Holdout, $Params);
2770:+		if ($BestFit['best'] == 0) {
2771:+			return array('error' => __('No method has enough history to be tested on the held out months'));
2772:+		}
2773:+		$Method = $BestFit['best'];
2774:+	}
2775:+	$Result = ForecastCompute($Method, $Series['values'], $Horizon, $Params);
2776:+	if (isset($Result['error'])) {
2777:+		return $Result;
2778:+	}
2779:+	$ForecastID = ForecastSave($StockID, $LocCode, $Method, $Params, $Series['start'], $HistoryEnd, ($BestFit !== null or $ChosenByBestFit), $Result['values']);
2780:+	return array('forecastid' => $ForecastID, 'method' => $Method, 'values' => $Result['values'], 'bestfit' => $BestFit, 'start' => $Series['start']);
2781:+}
