+function ForecastSolve($A, $B) {
+	$n = count($B);
+	for ($i = 0; $i < $n; $i++) {
+		$Pivot = $i;
+		for ($r = $i + 1; $r < $n; $r++) {
+			if (abs($A[$r][$i]) > abs($A[$Pivot][$i])) {
+				$Pivot = $r;
+			}
+		}
+		if (abs($A[$Pivot][$i]) < 1e-12) {
+			return null;
+		}
+		list($A[$i], $A[$Pivot]) = array($A[$Pivot], $A[$i]);
+		list($B[$i], $B[$Pivot]) = array($B[$Pivot], $B[$i]);
+		for ($r = $i + 1; $r < $n; $r++) {
+			$Factor = $A[$r][$i] / $A[$i][$i];
+			for ($c = $i; $c < $n; $c++) {
+				$A[$r][$c] -= $Factor * $A[$i][$c];
+			}
+			$B[$r] -= $Factor * $B[$i];
+		}
+	}
+	$X = array_fill(0, $n, 0);
+	for ($i = $n - 1; $i >= 0; $i--) {
+		$Sum = $B[$i];
+		for ($c = $i + 1; $c < $n; $c++) {
+			$Sum -= $A[$i][$c] * $X[$c];
+		}
+		$X[$i] = $Sum / $A[$i][$i];
+	}
+	return $X;
+}
