2166	+
2167	+		case 8:
2168	+			$Weights = array_values($P['weights']); // first weight is for the previous month, the second for the month before that...
2169	+			$v = $y;
2170	+			for ($k = 0; $k < $h; $k++) {
2171	+				$Sum = 0;
2172	+				foreach ($Weights as $i => $Weight) {
2173	+					$Sum += $Weight * $v[$n + $k - 1 - $i];
2174	+				}
2175	+				$v[$n + $k] = max(0, $Sum);
2176	+			}
2177	+			$f = array_slice($v, $n);
2178	+			break;
2179	+
2180	+		case 10:
2181	+			$Level = $y[0];
2182	+			for ($i = 1; $i < $n; $i++) {
2183	+				$Level = $P['alpha'] * $y[$i] + (1 - $P['alpha']) * $Level;
2184	+			}
2185	+			$f = array_fill(0, $h, $Level);
2186	+			break;
2187	+
2188	+		case 11:
2189	+			$Level = $y[0];
2190	+			$Trend = ($y[3] - $y[0]) / 3;
2191	+			for ($i = 1; $i < $n; $i++) {
2192	+				$PreviousLevel = $Level;
2193	+				$Level = $P['alpha'] * $y[$i] + (1 - $P['alpha']) * ($Level + $Trend);
2194	+				$Trend = $P['beta'] * ($Level - $PreviousLevel) + (1 - $P['beta']) * $Trend;
2195	+			}
2196	+			for ($k = 1; $k <= $h; $k++) {
2197	+				$f[] = $Level + $k * $Trend;
2198	+			}
2199	+			break;
2200	+
2201	+		case 12:
2202	+			$m = (int) $P['season'];
2203	+			$FirstMean = array_sum(array_slice($y, 0, $m)) / $m;
2204	+			$SecondMean = array_sum(array_slice($y, $m, $m)) / $m;
2205	+			$Trend = ($SecondMean - $FirstMean) / $m;
2206	+			$Level = $FirstMean + $Trend * ($m - 1) / 2;
2207	+			$Season = array();
2208	+			for ($i = 0; $i < $m; $i++) {
2209	+				$Season[$i] = $y[$i] - $FirstMean;
2210	+			}
2211	+			for ($i = $m; $i < $n; $i++) {
2212	+				$PreviousLevel = $Level;
2213	+				$Level = $P['alpha'] * ($y[$i] - $Season[$i % $m]) + (1 - $P['alpha']) * ($Level + $Trend);
2214	+				$Trend = $P['beta'] * ($Level - $PreviousLevel) + (1 - $P['beta']) * $Trend;
2215	+				$Season[$i % $m] = $P['gamma'] * ($y[$i] - $Level) + (1 - $P['gamma']) * $Season[$i % $m];
2216	+			}
2217	+			for ($k = 1; $k <= $h; $k++) {
2218	+				$f[] = $Level + $k * $Trend + $Season[($n - 1 + $k) % $m];
2219	+			}
2220	+			break;
2221	+	}
2222	+	return array('values' => ForecastFinish($f));
