2227	+/* MAD, MSE, RMSE and POA of forecasts against the actual sales of the same periods.
2228	+ * POA (percent of accuracy) is the forecast total as a percent of the actual total: 100 is a perfect total, above
2229	+ * 100 over forecast, below 100 under forecast. Null when there were no actual sales. */
2230	+function ForecastMetrics($Actual, $Forecast) {
2231	+	$n = count($Actual);
2232	+	$Metrics = array('n' => $n, 'mad' => 0, 'mse' => 0, 'rmse' => 0, 'poa' => null, 'actual' => 0, 'forecast' => 0);
2233	+	if ($n == 0) {
2234	+		return $Metrics;
2235	+	}
2236	+	$AbsError = $SquareError = 0;
2237	+	for ($i = 0; $i < $n; $i++) {
2238	+		$Error = $Actual[$i] - $Forecast[$i];
2239	+		$AbsError += abs($Error);
2240	+		$SquareError += $Error * $Error;
2241	+	}
2242	+	$Metrics['mad'] = $AbsError / $n;
2243	+	$Metrics['mse'] = $SquareError / $n;
2244	+	$Metrics['rmse'] = sqrt($Metrics['mse']);
2245	+	$Metrics['actual'] = array_sum($Actual);
2246	+	$Metrics['forecast'] = array_sum($Forecast);
2247	+	if ($Metrics['actual'] > 0) {
2248	+		$Metrics['poa'] = 100 * $Metrics['forecast'] / $Metrics['actual'];
2249	+	}
2250	+	return $Metrics;
2251	+}
