2257	+/* Hold out the last $Holdout months of the series, forecast them with every method the remaining history allows and
2258	+ * rank the methods by mean absolute deviation (root mean square error breaks ties).
2259	+ * Returns array('ranking' => id => metrics, best first, 'actual' => held out months) or array('error' => reason). */
2260	+function ForecastBestFit($Series, $Params, $Holdout) {
2261	+	$n = count($Series);
2262	+	$Methods = ForecastMethods();
2263	+	$Minimum = min(array_column($Methods, 'min'));
2264	+	if ($Holdout < 1 or $n - $Holdout < $Minimum) {
2265	+		return array('error' => sprintf(__('%d months of history is not enough to hold out %d months and still have the %d months the shortest method needs'), $n, $Holdout, $Minimum));
2266	+	}
2267	+	$Train = array_slice($Series, 0, $n - $Holdout);
2268	+	$Actual = array_slice($Series, $n - $Holdout);
2269	+	$Ranking = array();
2270	+	foreach ($Methods as $MethodID => $Method) {
2271	+		$Forecast = ForecastCompute($MethodID, $Train, $Holdout, $Params);
2272	+		if (isset($Forecast['error'])) {
2273	+			continue; // not applicable to this history
2274	+		}
2275	+		$Ranking[$MethodID] = ForecastMetrics($Actual, $Forecast['values']);
2276	+		$Ranking[$MethodID]['values'] = $Forecast['values'];
2277	+	}
2278	+	if (count($Ranking) == 0) {
2279	+		return array('error' => __('No method can be tested with this history'));
2280	+	}
2281	+	uasort($Ranking, function ($A, $B) {
2282	+		if (abs($A['mad'] - $B['mad']) > 1e-9) {
2283	+			return $A['mad'] < $B['mad'] ? -1 : 1;
2284	+		}
2285	+		return $A['rmse'] < $B['rmse'] ? -1 : ($A['rmse'] > $B['rmse'] ? 1 : 0);
2286	+	});
2287	+	return array('ranking' => $Ranking, 'actual' => $Actual);
2288	+}
