2290	+/* The method that does best across several series: every method is scored by its mean absolute deviation relative to
2291	+ * the average held out sales of the item (so large items do not decide alone), averaged over the items it could be
2292	+ * tested on. Only methods that could be tested on at least half of the items compete.
2293	+ * Returns array('method' => id or null, 'scores' => id => array('score', 'items'), 'items' => items tested) */
2294	+function ForecastBestFitForSet($SeriesSet, $Params, $Holdout) {
2295	+	$Totals = array();
2296	+	$Counts = array();
2297	+	$Tested = 0;
2298	+	foreach ($SeriesSet as $Series) {
2299	+		$Fit = ForecastBestFit($Series, $Params, $Holdout);
2300	+		if (isset($Fit['error'])) {
2301	+			continue;
2302	+		}
2303	+		$Mean = array_sum($Fit['actual']) / count($Fit['actual']);
2304	+		if ($Mean <= 0) {
2305	+			continue;
2306	+		}
2307	+		$Tested++;
2308	+		foreach ($Fit['ranking'] as $MethodID => $Metrics) {
2309	+			$Totals[$MethodID] = ($Totals[$MethodID] ?? 0) + $Metrics['mad'] / $Mean;
2310	+			$Counts[$MethodID] = ($Counts[$MethodID] ?? 0) + 1;
2311	+		}
2312	+	}
2313	+	$Result = array('method' => null, 'scores' => array(), 'items' => $Tested);
2314	+	foreach ($Totals as $MethodID => $Total) {
2315	+		$Result['scores'][$MethodID] = array('score' => $Total / $Counts[$MethodID], 'items' => $Counts[$MethodID]);
2316	+		if ($Counts[$MethodID] * 2 >= $Tested and ($Result['method'] === null or $Result['scores'][$MethodID]['score'] < $Result['scores'][$Result['method']]['score'])) {
2317	+			$Result['method'] = $MethodID;
2318	+		}
2319	+	}
2320	+	return $Result;
2321	+}
