2324	+
2325	+/* Forecast a series with the chosen method, or with the best fit when $MethodID is 0 (the methods are then tried
2326	+ * best first until one can forecast the full history).
2327	+ * Returns array('method' => id, 'values' => array, 'params' => stored parameters) or array('error' => reason) */
2328	+function ForecastRunSeries($Series, $MethodID, $Horizon, $Params, $Holdout) {
2329	+	$Values = $Series['values'];
2330	+	if (count($Values) == 0) {
2331	+		return array('error' => __('No sales history'));
2332	+	}
2333	+	$Selection = 'manual';
2334	+	if ($MethodID == 0) {
2335	+		$Fit = ForecastBestFit($Values, $Params, $Holdout);
2336	+		if (isset($Fit['error'])) {
2337	+			return array('error' => $Fit['error']);
2338	+		}
2339	+		$Selection = 'bestfit';
2340	+		foreach ($Fit['ranking'] as $Candidate => $Metrics) {
2341	+			$Forecast = ForecastCompute($Candidate, $Values, $Horizon, $Params);
2342	+			if (!isset($Forecast['error'])) {
2343	+				$MethodID = $Candidate;
2344	+				$Accuracy = $Metrics;
2345	+				break;
2346	+			}
2347	+		}
2348	+		if ($MethodID == 0) {
2349	+			return array('error' => __('No method can forecast this history'));
2350	+		}
2351	+	} else {
2352	+		$Forecast = ForecastCompute($MethodID, $Values, $Horizon, $Params);
2353	+		if (isset($Forecast['error'])) {
2354	+			return array('error' => $Forecast['error']);
2355	+		}
2356	+	}
2357	+	$Stored = $Params;
2358	+	$Stored['selection'] = $Selection;
2359	+	if (isset($Accuracy)) {
2360	+		$Stored['holdout'] = $Holdout;
2361	+		$Stored['holdoutmad'] = round($Accuracy['mad'], 4);
2362	+	}
2363	+	return array('method' => $MethodID, 'values' => $Forecast['values'], 'params' => $Stored);
2364	+}
