2452	+
2453	+/* Convert the active forecasts into MRP demands of the forecast demand type.
2454	+ * The demands written are listed in forecastmrplinks. Only linked demands are ever removed or counted as present,
2455	+ * so demands entered by hand or from other sources are never touched, even if they use the same demand type.
2456	+ *  - replace: the linked demands of the items converted that fall in the horizon are deleted first
2457	+ *  - incremental: the periods that already have a linked demand are left alone
2458	+ * Either way converting twice gives the same demands, never double.
2459	+ * An item with an active forecast for all locations is converted from that forecast; an item that only has location
2460	+ * forecasts is converted from the sum of them, so no sale is counted twice.
2461	+ * $FromMonth and $ToMonth are first-of-month dates; the demand of a period is due on the first day of its month.
2462	+ * Returns array('items' => converted, 'created' => demands written, 'removed' => demands deleted, 'skipped' => periods
2463	+ * already there). */
2464	+function ForecastConvertToMRP($FromMonth, $ToMonth, $Mode, $CategoryID = '', $StockID = '') {
2465	+	$Summary = array('items' => 0, 'created' => 0, 'removed' => 0, 'skipped' => 0);
2466	+	$ToDate = date('Y-m-t', strtotime($ToMonth));
2467	+
2468	+	$SQL = "SELECT forecasts.forecastid,
2469	+					forecasts.stockid,
2470	+					forecasts.loccode,
2471	+					forecastdetails.periodmonth,
2472	+					" . FORECAST_EFFECTIVE_QTY . " AS qty
2473	+			FROM forecasts
2474	+			INNER JOIN forecastdetails ON forecastdetails.forecastid = forecasts.forecastid
2475	+			INNER JOIN stockmaster ON stockmaster.stockid = forecasts.stockid
2476	+			WHERE forecasts.activeslot = 1
2477	+				AND stockmaster.discontinued = 0
2478	+				AND forecastdetails.periodmonth BETWEEN '" . $FromMonth . "' AND '" . $ToMonth . "'";
2479	+	if ($CategoryID != '') {
2480	+		$SQL .= " AND stockmaster.categoryid='" . $CategoryID . "'";
2481	+	}
2482	+	if ($StockID != '') {
2483	+		$SQL .= " AND forecasts.stockid='" . $StockID . "'";
2484	+	}
2485	+	$Result = DB_query($SQL);
2486	+
2487	+	// per item: the all locations forecast when there is one, else all the location forecasts
2488	+	$Rows = array();
2489	+	$HasAllLocations = array();
2490	+	while ($MyRow = DB_fetch_array($Result)) {
2491	+		$Rows[] = $MyRow;
2492	+		if ($MyRow['loccode'] == '') {
2493	+			$HasAllLocations[$MyRow['stockid']] = true;
2494	+		}
2495	+	}
2496	+	$Demands = array(); // stockid => month => array(quantity, forecastid)
2497	+	foreach ($Rows as $MyRow) {
2498	+		if ($MyRow['loccode'] != '' and isset($HasAllLocations[$MyRow['stockid']])) {
2499	+			continue;
2500	+		}
2501	+		if (!isset($Demands[$MyRow['stockid']][$MyRow['periodmonth']])) {
2502	+			$Demands[$MyRow['stockid']][$MyRow['periodmonth']] = array(0, $MyRow['forecastid']);
2503	+		}
2504	+		$Demands[$MyRow['stockid']][$MyRow['periodmonth']][0] += max(0, $MyRow['qty']);
2505	+	}
2506	+	if (count($Demands) == 0) {
2507	+		return $Summary;
2508	+	}
2509	+
2510	+	$LinkedDemands = "SELECT demandid FROM forecastmrplinks";
2511	+	DB_Txn_Begin();
2512	+	foreach (array_chunk(array_keys($Demands), 200) as $Chunk) {
2513	+		$ItemList = "'" . implode("','", $Chunk) . "'";
2514	+		if ($Mode == 'replace') {
2515	+			$Where = "mrpdemandtype='" . FORECAST_MRP_DEMAND_TYPE . "'
2516	+						AND demandid IN (" . $LinkedDemands . ")
2517	+						AND stockid IN (" . $ItemList . ")
2518	+						AND duedate BETWEEN '" . $FromMonth . "' AND '" . $ToDate . "'";
2519	+			$Result = DB_query("SELECT COUNT(*) FROM mrpdemands WHERE " . $Where, '', '', true);
2520	+			$MyRow = DB_fetch_row($Result);
2521	+			$Summary['removed'] += (int) $MyRow[0];
2522	+			DB_query("DELETE FROM mrpdemands WHERE " . $Where, '', '', true);
2523	+		}
2524	+	}
2525	+	$Present = array();
2526	+	if ($Mode != 'replace') {
2527	+		foreach (array_chunk(array_keys($Demands), 200) as $Chunk) {
2528	+			$Result = DB_query("SELECT mrpdemands.stockid, mrpdemands.duedate
2529	+								FROM mrpdemands
2530	+								INNER JOIN forecastmrplinks ON forecastmrplinks.demandid = mrpdemands.demandid
2531	+								WHERE mrpdemands.mrpdemandtype='" . FORECAST_MRP_DEMAND_TYPE . "'
2532	+									AND mrpdemands.stockid IN ('" . implode("','", $Chunk) . "')
2533	+									AND mrpdemands.duedate BETWEEN '" . $FromMonth . "' AND '" . $ToDate . "'", '', '', true);
2534	+			while ($MyRow = DB_fetch_array($Result)) {
2535	+				$Present[$MyRow['stockid']][ForecastMonthStart($MyRow['duedate'])] = true;
2536	+			}
2537	+		}
2538	+	}
2539	+	foreach ($Demands as $Item => $Periods) {
2540	+		$ItemCreated = 0;
2541	+		foreach ($Periods as $Month => $Demand) {
2542	+			if ($Demand[0] <= 0) {
2543	+				continue;
2544	+			}
2545	+			if (isset($Present[$Item][$Month])) {
2546	+				$Summary['skipped']++;
2547	+				continue;
2548	+			}
2549	+			DB_query("INSERT INTO mrpdemands (stockid, mrpdemandtype, quantity, duedate)
2550	+					VALUES ('" . $Item . "', '" . FORECAST_MRP_DEMAND_TYPE . "', " . round($Demand[0], 4) . ", '" . $Month . "')", '', '', true);
2551	+			$DemandID = DB_Last_Insert_ID('mrpdemands', 'demandid');
2552	+			DB_query("INSERT INTO forecastmrplinks (demandid, forecastid, periodmonth)
2553	+					VALUES (" . $DemandID . ", " . $Demand[1] . ", '" . $Month . "')", '', '', true);
2554	+			$ItemCreated++;
2555	+		}
2556	+		$Summary['created'] += $ItemCreated;
2557	+		$Summary['items']++;
2558	+	}
2559	+	DB_Txn_Commit();
2560	+	return $Summary;
2561	+}
