2160	+	$Params = array();
2161	+
2162	+	// a field that was filled in but is not a number is an error, an empty or absent one takes the default
2163	+	$Scalar = function ($Field, $Key, $Default, $Message) use ($Input, &$Errors) {
2164	+		if (!isset($Input[$Field]) or trim($Input[$Field]) === '') {
2165	+			return (float) $Default;
2166	+		}
2167	+		$Number = ForecastNumber($Input[$Field]);
2168	+		if ($Number === null) {
2169	+			$Errors[$Key] = $Message;
