2173	+	};
2174	+
2175	+	$Params['p'] = $Scalar('GrowthPercent', 'p', $Defaults['GrowthPercent'], __('The percent over last year must be a number'));
2176	+	if ($Params['p'] < -100 or $Params['p'] > 1000) {
