2194	+	} elseif (count($Params['weights']) < 2 or count($Params['weights']) > 12 or array_sum($Params['weights']) <= 0) {
2195	+		$Errors['weights'] = __('Enter between 2 and 12 weights that add up to more than zero');
2196	+	}
2197	+
