2199	+	if ($Params['flex'] === null) {
2200	+		$Params['flex'] = array();
2201	+		$Errors['flex'] = __('The flexible weights must be positive numbers separated by slashes');
2202	+	} elseif (count($Params['flex']) != 12 or array_sum($Params['flex']) <= 0) {
2203	+		$Errors['flex'] = __('Enter exactly 12 flexible weights, one for each of the prior 12 months, that add up to more than zero');
2204	+	}
2205	+
2206	+	foreach (array('alpha' => 'Alpha', 'beta' => 'Beta', 'gamma' => 'Gamma') as $Key => $Field) {
2207	+		$Params[$Key] = $Scalar($Field, $Key, $Defaults[$Field], $Field . ': ' . __('the smoothing constants must be numbers'));
2208	+		if ($Params[$Key] < 0.1 or $Params[$Key] > 0.9) {
2209	+			$Errors[$Key] = $Field . ': ' . __('the smoothing constants must be between 0.1 and 0.9');
2210	+		}
2211	+	}
2212	+
2213	+	$Params['season'] = (int) $Scalar('SeasonLength', 'season', $Defaults['SeasonLength'], __('The season length must be a number'));
2214	+	if ($Params['season'] < 2 or $Params['season'] > 12) {
2215	+		$Errors['season'] = __('The season length must be between 2 and 12 months');
2216	+	}
2217	+
2218	+	return array($Params, $Errors);
2219	+}
2220	+
2221	+/* A decimal typed by the user: either separator is accepted for a plain decimal such as 0,3 or 0.3, anything else
2222	+goes through the number format of the user's locale. Returns null when it is not a number. */
2223	+function ForecastNumber($Text) {
2224	+	$Text = trim($Text);
2225	+	if (preg_match('/^-?\d+([.,]\d+)?$/', $Text)) {
2226	+		return (float) str_replace(',', '.', $Text);
2227	+	}
2228	+	$Clean = filter_number_format($Text);
2229	+	return is_numeric($Clean) ? (float) $Clean : null;
2230	+}
2231	+
2232	+/* Non-negative numbers separated by slashes, semicolons or spaces (commas too where the decimal point is not one).
2233	+Returns the list, or null when an entry is not a non-negative number. */
2234	+function ForecastParseList($Text) {
2235	+	global $DecimalPoint;
2236	+	$Separators = ($DecimalPoint == ',') ? '[\/;\s]+' : '[\/;,\s]+';
2237	+	$Numbers = array();
2238	+	foreach (preg_split('/' . $Separators . '/', trim($Text), -1, PREG_SPLIT_NO_EMPTY) as $Entry) {
2239	+		$Number = ForecastNumber($Entry);
2240	+		if ($Number === null or $Number < 0) {
2241	+			return null;
2242	+		}
2243	+		$Numbers[] = $Number;
2244	+	}
2245	+	return $Numbers;
2246	+}
2247	+
2248	+/* The errors that matter for the method chosen (0 = best fit tries every method, so all of them matter) */
2249	+function ForecastRelevantErrors($Errors, $Method) {
2250	+	if ($Method == 0) {
2251	+		return array_values($Errors);
2252	+	}
2253	+	$Relevant = array();
2254	+	foreach (ForecastMethodParamKeys($Method) as $Key) {
2255	+		if (isset($Errors[$Key])) {
2256	+			$Relevant[] = $Errors[$Key];
2257	+		}
2258	+	}
2259	+	return $Relevant;
2260	+}
2261	+
2262	+/* The parameters of the method as they are stored with a forecast: only those the method uses */
2263	+function ForecastParamsEncode($Method, $Params) {
2264	+	$Used = array();
2265	+	foreach (ForecastMethodParamKeys($Method) as $Key) {
2266	+		$Used[$Key] = $Params[$Key];
2267	+	}
2268	+	return json_encode($Used);
2269	+}
2270	+
2271	+function ForecastParamsDecode($Encoded) {
2272	+	$Params = json_decode($Encoded, true);
2273	+	return is_array($Params) ? $Params : array();
2274	+}
2275	+
2276	+function ForecastParamsDescribe($Method, $Encoded) {
2277	+	$Params = ForecastParamsDecode($Encoded);
2278	+	$Labels = ForecastParamLabels();
2279	+	$Text = array();
2280	+	foreach (ForecastMethodParamKeys($Method) as $Key) {
2281	+		if (!isset($Params[$Key])) {
2282	+			continue;
2283	+		}
2284	+		$Value = is_array($Params[$Key]) ? implode('/', $Params[$Key]) : $Params[$Key];
2285	+		$Text[] = $Labels[$Key] . ': ' . $Value;
2286	+	}
2287	+	return implode('; ', $Text);
2288	+}
2289	+
2290	+/* ------------------------------------------------------------------- methods */
2291	+
2292	+/* Forecasts $Horizon months after the end of $Series with $Method.
2293	+Returns array('values' => list of quantities, never negative) or array('error' => reason) */
2294	+function ForecastCompute($Method, $Series, $Horizon, $Params) {
2295	+	$Series = array_values($Series);
2296	+	$n = count($Series);
2297	+	$Min = ForecastMethodMinHistory($Method);
2298	+	if ($Min === null) {
2299	+		return array('error' => __('Unknown forecasting method'));
2300	+	}
2301	+	if ($n < $Min) {
2302	+		return array('error' => sprintf(__('Only %d months of history, the method needs at least %d'), $n, $Min));
2303	+	}
2304	+	$Horizon = (int) $Horizon;
2305	+	$F = array();
2306	+
2307	+	switch ($Method) {
2308	+		case 1: // percent over last year
2309	+		case 2: // calculated percent over last year
2310	+		case 3: // last year to this year
2311	+			if ($Method == 1) {
2312	+				$Factor = 1 + $Params['p'] / 100;
2313	+			} elseif ($Method == 3) {
2314	+				$Factor = 1;
2315	+			} else {
2316	+				$LastYear = array_sum(array_slice($Series, $n - 12, 12));
2317	+				$YearBefore = array_sum(array_slice($Series, $n - 24, 12));
2318	+				if ($YearBefore <= 0) {
2319	+					return array('error' => __('There were no sales in the year before last year, so the growth cannot be calculated'));
2320	+				}
2321	+				$Factor = $LastYear / $YearBefore;
2322	+			}
2323	+			// beyond 12 months the "same month last year" is itself a forecast
2324	+			$Extended = $Series;
2325	+			for ($k = 1; $k <= $Horizon; $k++) {
2326	+				$Value = max(0, $Extended[$n + $k - 1 - 12] * $Factor);
2327	+				$Extended[] = $Value;
2328	+				$F[] = $Value;
2329	+			}
2330	+			break;
2331	+
2332	+		case 4: // moving average of the last N periods
2333	+			$N = (int) $Params['n'];
2334	+			if ($N < 2 or $N > $n) {
2335	+				return array('error' => sprintf(__('The moving average of %d periods needs at least that many months of history'), $N));
2336	+			}
2337	+			$Average = array_sum(array_slice($Series, $n - $N, $N)) / $N;
2338	+			$F = array_fill(0, $Horizon, max(0, $Average));
2339	+			break;
2340	+
2341	+		case 5: // line through two historical points
2342	+			$Span = (int) $Params['span'];
2343	+			if ($Span < 2 or $Span > $n) {
2344	+				return array('error' => sprintf(__('The two points are %d months apart but there are only %d months of history'), $Span, $n));
2345	+			}
2346	+			$Last = $Series[$n - 1];
2347	+			$Slope = ($Last - $Series[$n - $Span]) / ($Span - 1);
2348	+			for ($k = 1; $k <= $Horizon; $k++) {
2349	+				$F[] = max(0, $Last + $Slope * $k);
2350	+			}
2351	+			break;
2352	+
2353	+		case 6: // least squares line over all history
2354	+			$SumT = 0;
2355	+			$SumT2 = 0;
2356	+			$SumY = 0;
2357	+			$SumTY = 0;
2358	+			for ($i = 0; $i < $n; $i++) {
2359	+				$t = $i + 1;
2360	+				$SumT += $t;
2361	+				$SumT2 += $t * $t;
2362	+				$SumY += $Series[$i];
2363	+				$SumTY += $t * $Series[$i];
2364	+			}
2365	+			$Denominator = $n * $SumT2 - $SumT * $SumT;
2366	+			$B = ($n * $SumTY - $SumT * $SumY) / $Denominator;
2367	+			$A = ($SumY - $B * $SumT) / $n;
2368	+			for ($k = 1; $k <= $Horizon; $k++) {
2369	+				$F[] = max(0, $A + $B * ($n + $k));
2370	+			}
2371	+			break;
2372	+
2373	+		case 7: // least squares parabola over all history, on centred time to keep the equations well conditioned
2374	+			$Mean = ($n + 1) / 2;
2375	+			$S2 = 0;
2376	+			$S4 = 0;
2377	+			$SumY = 0;
2378	+			$SumXY = 0;
2379	+			$SumX2Y = 0;
2380	+			for ($i = 0; $i < $n; $i++) {
2381	+				$x = ($i + 1) - $Mean;
2382	+				$S2 += $x * $x;
2383	+				$S4 += $x * $x * $x * $x;
2384	+				$SumY += $Series[$i];
2385	+				$SumXY += $x * $Series[$i];
2386	+				$SumX2Y += $x * $x * $Series[$i];
2387	+			}
2388	+			$Determinant = $n * $S4 - $S2 * $S2;
2389	+			if ($Determinant <= 0 or $S2 <= 0) {
2390	+				return array('error' => __('The second degree approximation cannot be solved for this history'));
2391	+			}
2392	+			$A = ($SumY * $S4 - $S2 * $SumX2Y) / $Determinant;
2393	+			$B = $SumXY / $S2;
2394	+			$C = ($n * $SumX2Y - $S2 * $SumY) / $Determinant;
2395	+			for ($k = 1; $k <= $Horizon; $k++) {
2396	+				$x = ($n + $k) - $Mean;
2397	+				$F[] = max(0, $A + $B * $x + $C * $x * $x);
2398	+			}
2399	+			break;
2400	+
2401	+		case 8: // flexible: the user's weights on each of the prior 12 months, not normalised
2402	+			$Weights = array_values($Params['flex']);
2403	+			if (count($Weights) != 12 or array_sum($Weights) <= 0) {
2404	+				return array('error' => __('Enter exactly 12 flexible weights, one for each of the prior 12 months, that add up to more than zero'));
2405	+			}
2406	+			$Extended = $Series;
2407	+			for ($k = 1; $k <= $Horizon; $k++) {
2408	+				$Index = $n + $k - 1;
2409	+				$Value = 0;
2410	+				for ($Lag = 1; $Lag <= 12; $Lag++) {
2411	+					$Value += $Weights[$Lag - 1] * $Extended[$Index - $Lag];
2412	+				}
2413	+				$Value = max(0, $Value);
2414	+				$Extended[] = $Value;
2415	+				$F[] = $Value;
2416	+			}
2417	+			break;
2418	+
2419	+		case 9: // weighted moving average, weights listed most recent period first
2420	+			$Weights = array_values($Params['weights']);
2421	+			$N = count($Weights);
2422	+			if ($N < 2 or $N > $n or array_sum($Weights) <= 0) {
2423	+				return array('error' => sprintf(__('The %d weights need at least that many months of history and must add up to more than zero'), $N));
2424	+			}
2425	+			$Value = 0;
2426	+			for ($i = 0; $i < $N; $i++) {
2427	+				$Value += $Weights[$i] * $Series[$n - 1 - $i];
2428	+			}
2429	+			$F = array_fill(0, $Horizon, max(0, $Value / array_sum($Weights)));
2430	+			break;
2431	+
2432	+		case 10: // simple exponential smoothing
2433	+			$Alpha = $Params['alpha'];
2434	+			$Level = $Series[0];
2435	+			for ($i = 1; $i < $n; $i++) {
2436	+				$Level = $Alpha * $Series[$i] + (1 - $Alpha) * $Level;
2437	+			}
2438	+			$F = array_fill(0, $Horizon, max(0, $Level));
