+function ForecastAddMonths($MonthStart, $Months) {
+	$Date = new DateTime($MonthStart);
+	$Date->modify('first day of this month');
+	if ($Months != 0) {
+		$Date->modify(($Months > 0 ? '+' : '') . (int) $Months . ' month');
+	}
+	return $Date->format('Y-m-d');
+}
