+/* 'YYYY-MM' (month input) or any date to the first day of its month, or null when invalid */
+function ForecastMonthStart($Text) {
+	if (preg_match('/^(\d{4})-(\d{2})(-\d{2})?$/', trim($Text), $Matches) and $Matches[2] >= 1 and $Matches[2] <= 12) {
+		return $Matches[1] . '-' . $Matches[2] . '-01';
+	}
+	return null;
+}
+
+function ForecastMonthLabel($MonthStart) {
+	return date('M Y', strtotime($MonthStart));
+}
+
+function ForecastLastCompleteMonth() {
+	return ForecastAddMonths(date('Y-m-01'), -1);
+}
