+							MAX(monthstart) AS lastmonth,
+							COUNT(DISTINCT stockid) AS items,
+							COUNT(DISTINCT monthstart) AS months,
+							COUNT(*) AS historyrows
+						FROM forecasthistory");
+	$MyRow = DB_fetch_array($Result);
+	return array('from' => $MyRow['firstmonth'], 'to' => $MyRow['lastmonth'], 'items' => (int) $MyRow['items'], 'months' => (int) $MyRow['months'], 'rows' => (int) $MyRow['historyrows']);
+}
