+/* Replaces the history of the months $From to $To (first days of months) with net invoiced sales: invoices (type 10)
+less credit notes (type 11) from the stock movements, the same source as the inventory planning and sales reports.
+Returns the number of history rows written. */
+function ForecastExtractHistory($From, $To) {
+	$LastDay = date('Y-m-t', strtotime($To));
+	DB_Txn_Begin();
+	DB_query("DELETE FROM forecasthistory WHERE monthstart >= '" . $From . "' AND monthstart <= '" . $To . "'", '', '', true);
+	$Result = DB_query("INSERT INTO forecasthistory (stockid, loccode, monthstart, debtortype, area, salesman, qty)
+						SELECT stockmoves.stockid,
+							stockmoves.loccode,
+							DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
+							COALESCE(debtorsmaster.typeid, 0),
+							COALESCE(custbranch.area, ''),
+							COALESCE(custbranch.salesman, ''),
+							-SUM(stockmoves.qty)
+						FROM stockmoves
+						LEFT JOIN debtorsmaster ON debtorsmaster.debtorno = stockmoves.debtorno
+						LEFT JOIN custbranch ON custbranch.debtorno = stockmoves.debtorno
+							AND custbranch.branchcode = stockmoves.branchcode
+						WHERE stockmoves.type IN (10, 11)
+							AND stockmoves.hidemovt = 0
+							AND stockmoves.trandate >= '" . $From . "'
+							AND stockmoves.trandate <= '" . $LastDay . "'
+						GROUP BY stockmoves.stockid,
+							stockmoves.loccode,
+							DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
+							COALESCE(debtorsmaster.typeid, 0),
+							COALESCE(custbranch.area, ''),
+							COALESCE(custbranch.salesman, '')", '', '', true);
+	$Rows = DB_affected_rows($Result);
+	DB_Txn_Commit();
+	return $Rows;
+}
